Contract AutomatedTellerMachineSystem::printReceipt(): Real {
          definition:
          inputCard:BankCard = BankCard.allInstance()->any(o | o = self.InputCard)

            precondition:
          self.CardIDValidated = true and self.PasswordValidated = true and BankCard.allInstance()->includes(inputCard)

            postcondition:
          let result:Real in (self.CardIDValidated and self.PasswordValidated and inputCard.oclIsUndefined() = false) and (if self.IsDeposit then result = self.DepositedNumber else result = 0.0 endif)

        }
